def solve(data):
    s = data["s"]

    # Edge cases
    if not s or len(s) == 0:
        return 0

    if len(s) % 2 != 0:
        return -1

    max_depth = 0
    current_depth = 0

    for char in s:
        if char == '(':
            current_depth += 1
            max_depth = max(max_depth, current_depth)
        elif char == ')':
            current_depth -= 1

    if current_depth != 0:
        return -1

    return max_depth

