class Solution:
    def solve(self, data: Dict[str, str]) -> Union[int, str]:
        # Edge cases
        if not data['s']:
            return 0

        # Brute-force approach
        max_depth = 0
        current_depth = 0
        for char in data['s']:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        if current_depth != 0:
            return -1

        # Efficient solution
        stack = []
        max_depth = 0
        for char in data['s']:
            if char == '(':
                stack.append(char)
                max_depth = max(max_depth, len(stack))
            elif char == ')':
                stack.pop()

        if len(stack) > 0:
            return -1

        return max_depth
